<?php if (!defined('__TYPECHO_ROOT_DIR__')) exit; ?>
<section class="comments" id="comments"><div class="section-heading"><div><p class="eyebrow">CONVERSATION</p><h2><?php $this->commentsNum(_t('暂无回应'), _t('1 条回应'), _t('%d 条回应')); ?></h2></div></div><?php $this->comments()->to($comments); ?><?php if ($comments->have()): ?><ol class="comment-list"><?php while ($comments->next()): ?><li class="comment"><div class="comment-avatar"><?php $authorName = trim((string) $comments->author); if (function_exists('mb_substr')) { $authorInitial = mb_substr($authorName, 0, 1, 'UTF-8'); } elseif (function_exists('iconv_substr')) { $authorInitial = iconv_substr($authorName, 0, 1, 'UTF-8'); } else { $authorInitial = substr($authorName, 0, 1); } echo strtoupper($authorInitial ?: 'L'); ?></div><div><div class="comment-meta"><strong><?php $comments->author(); ?></strong><time><?php $comments->date('Y.m.d H:i'); ?></time></div><div class="comment-content"><?php $comments->content(); ?></div></div></li><?php endwhile; ?></ol><?php endif; ?><?php if ($this->allow('comment')): ?><div class="comment-form"><?php $comments->respond(); ?></div><?php else: ?><p class="comment-closed">评论已关闭。</p><?php endif; ?></section>
